import json, numpy as np
from PIL import Image
from pathlib import Path
p=Path('/app/output/000_initial'); m=json.loads((p/'meta.json').read_text())
def xyz(cam):
    d=np.load(p/f'last_depth_{cam}.npy'); K=np.array(m['cameras'][cam]['intrinsic_cv']); E=np.array(m['cameras'][cam]['extrinsic_cv']);
    v,u=np.indices(d.shape); pc=np.stack(((u-K[0,2])*d/K[0,0], (v-K[1,2])*d/K[1,1],d),-1)
    return (pc-E[:,3])@E[:,:3]
for cam in m['cameras']:
    pts=xyz(cam); im=np.asarray(Image.open(p/'last'/f'{cam}.jpg')); r,g,b=im.astype(float).transpose(2,0,1)
    mask=(r>130)&(g>110)&(b<80)&(g>r*.78)&(pts[:,:,2]>.005)&(pts[:,:,0]>.4)&(pts[:,:,0]<.85)&(abs(pts[:,:,1])<.1)
    ps=pts[mask]; print(cam,'yellow',len(ps),'xyz quantiles',np.round(np.quantile(ps,[.01,.1,.5,.9,.99],axis=0),4).tolist())
    for z in np.arange(0,.22,.02):
        q=ps[(ps[:,2]>=z)&(ps[:,2]<z+.02)]
        if len(q): print('z',round(z,2),'n',len(q),'xy min/median/max',np.round(np.quantile(q[:,:2],[.02,.5,.98],axis=0),4).tolist())
    if cam=='egocentric_mirrored_camera':
        for u,v in [(650,225),(620,160),(690,290),(560,200),(730,200),(432,310),(432,180),(432,200),(432,250),(200,220)]: print('pixel',u,v,'xyz',pts[v,u].round(4).tolist())
